function renderPlayers(){const mafiaVisible=new Set(priv?.game==='mafia'?(priv.mafiaIds||[]):[]);const talkPhase=state.game==='liar'&&((state.mode==='normal'&&state.phase==='play')||(state.mode==='question'&&state.phase==='reveal'));const rTurn=state.game==='rummi'?state.rummi?.turnPlayerId:null,wTurn=state.game==='wordchain'?state.wordchain?.turnPlayerId:null;$('#players').innerHTML=state.players.map((p,pi)=>{const dead=state.game==='mafia'&&!p.alive,maf=state.game==='mafia'&&mafiaVisible.has(p.id),starter=talkPhase&&p.id===state.discussionStarterId,rTurnNow=state.game==='rummi'&&p.id===rTurn,wTurnNow=state.game==='wordchain'&&p.id===wTurn,wDead=state.game==='wordchain'&&state.wordchain?.eliminated?.[p.id];let status=p.connected?'<span class="status-online">● 접속 중</span>':'<span class="status-offline">접속 끊김 🔌</span>';if(p.rolePublic)status=`역할: ${role(p.rolePublic)}`;if(state.game==='rummi'&&state.rummi?.rackCounts)status=`남은 타일 <b>${state.rummi.rackCounts[p.id]??0}개</b>`;if(state.game==='wordchain'&&state.wordchain)status=`${'❤️'.repeat(state.wordchain.lives?.[p.id]||0)}${wDead?' · 💀 탈락':''}`;if(state.game==='stockwar'&&state.stock?.loanUsers?.includes(p.id))status+='<span class="genius-stat">🏦 대출 사용</span>';const starterBadge=starter?`<div class="first-speaker ${state.discussionDirection==='left'?'left':'right'}">${state.discussionDirection==='left'?'← 선':'선 →'}</div>`:'';const incoming=state.game==='stockwar'&&p.id!==me?(priv?.messages||[]).filter(m=>!m.own&&m.from===p.id).length:0,unread=Math.max(0,incoming-(stockReadCounts[p.id]||0));const stockActions=state.game==='stockwar'&&p.id!==me?`<div class="stock-player-actions"><button data-stock-chat="${p.id}">대화${unread?` <span class="chat-bubble">${unread}</span>`:''}</button><button data-stock-pay="${p.id}">송금</button></div>`:'';const zincoming=state.game==='zombie'&&p.id!==me?(priv?.messages||[]).filter(m=>!m.own&&m.from===p.id).length:0,zunread=Math.max(0,zincoming-(zombieReadCounts[p.id]||0));const zombieActions=state.game==='zombie'&&p.id!==me?`<div class="zombie-player-actions"><button data-zombie-chat="${p.id}">대화${zunread?` <span class="chat-bubble">${zunread}</span>`:''}</button>${state.phase==='zombiePlay'?`<button data-zombie-touch="${p.id}">접촉</button>`:''}</div>`:'';const geniusMode=['genius','stockwar','zombie','smuggling'].includes(state.game),gi=Number.isInteger(p.geniusColorIndex)?p.geniusColorIndex:pi%10,gcols=['#ef4444','#f97316','#facc15','#22c55e','#3b82f6','#a855f7','#38bdf8','#f8fafc','#8b5e3c','#111111'],gicons=['♥','♥','♥','♥','♥','♥','♥','♥','♥','♥'];return `<div data-player-id="${p.id}" class="player ${dead?'dead':''} ${maf?'mafia-mark':''} ${starter?'first-speaker-player':''} ${rTurnNow?'rummi-current-player':''} ${wTurnNow?'wordchain-current-player':''} ${wDead?'wordchain-dead':''} ${geniusMode?'genius-player':''} ${state.game==='mafia'&&priv?.loverId===p.id?'lover-player':''}" ${geniusMode?`style="--player-color:${gcols[gi]}"`:''}>${starterBadge}<div class="face">${geniusMode?`<span class="genius-token">${gicons[gi]}</span>`:avatarHtml(p.avatar)}</div><div class="name">${esc(p.name)} ${p.id===state.hostId?'👑':''}${p.isBot?'<span class="bot-badge">🤖 BOT</span>':''}</div><div class="score">${status}</div>${dead?'<div class="death-badge">💀 사망</div>':''}${maf?'<div class="mafia-badge">🔪 마피아</div>':''}${stockActions}${zombieActions}</div>`}).join('');bindStockPlayerActions();bindZombiePlayerActions()}

