function renderSettings(){
 const e=$('#settings');if(!host()||state.phase!=='lobby'){e.classList.add('hidden');return}e.classList.remove('hidden');
 let h=`<h3>방 설정</h3><div class="settings-grid"><label>게임 변경<select id="sGame">${Object.entries(labels).filter(([k])=>!['stockwar','zombie','smuggling'].includes(k)).map(([k,v])=>`<option value="${k}" ${state.game===k?'selected':''}>${v} · ${mins[k]}~${maxes[k]}명</option>`).join('')}</select></label>`;
 if(state.game==='genius')h+=`<label>지니어스게임 선택<select id="sGeniusGame"><option value="stockwar" ${state.settings.geniusGame==='stockwar'?'selected':''}>📈 주식전쟁 · 약 40분</option><option value="zombie" ${state.settings.geniusGame==='zombie'?'selected':''}>🧟 좀비게임 · 약 25분</option><option value="smuggling" ${state.settings.geniusGame==='smuggling'?'selected':''}>🧳 밀수 · 약 35분</option></select></label>`;
 if(state.game==='liar')h+=`<label>세부 게임<select id="sMode"><option value="normal" ${state.mode==='normal'?'selected':''}>단어게임</option><option value="question" ${state.mode==='question'?'selected':''}>질문게임</option></select></label>${state.mode==='normal'?`<label>라이어 모드<select id="sRoleMode"><option value="liar" ${state.settings.liarRoleMode==='liar'?'selected':''}>일반모드 · 라이어는 단어를 모름</option><option value="fool" ${['fool','spy'].includes(state.settings.liarRoleMode)?'selected':''}>바보모드 · 한 명만 다른 단어</option><option value="random" ${state.settings.liarRoleMode==='random'?'selected':''}>랜덤 🎲</option></select></label>`:''}<label>라이어 수<select id="sLiar"><option ${state.settings.liarCount==1?'selected':''}>1</option><option ${state.settings.liarCount==2?'selected':''}>2</option><option ${state.settings.liarCount==3?'selected':''}>3</option></select></label><label>매치 방식<select id="sLiarMatch"><option value="1" ${state.settings.liarMatch==='1'?'selected':''}>한 판</option><option value="5" ${state.settings.liarMatch!=='1'?'selected':''}>5라운드</option></select></label>${state.mode==='normal'?`<label>1인 발언 시간<select id="sLiarTalk"><option value="20" ${state.settings.liarTalkTime==20?'selected':''}>20초</option><option value="25" ${state.settings.liarTalkTime==25?'selected':''}>25초</option><option value="30" ${state.settings.liarTalkTime==30?'selected':''}>30초</option></select></label>`:''}`;
 if(state.game==='truth')h+=`<label>질문 단계<select id="sTruth"><option value="easy" ${state.settings.truthLevel==='easy'?'selected':''}>이지 😊</option><option value="normal" ${state.settings.truthLevel==='normal'?'selected':''}>노멀 😏</option><option value="hard" ${state.settings.truthLevel==='hard'?'selected':''}>하드 🔥</option></select></label>`;
 if(state.game==='wordchain')h+=`<label>게임 모드<select id="sWMode"><option value="normal" ${state.settings.wordchainMode==='normal'?'selected':''}>일반 모드</option><option value="speed" ${state.settings.wordchainMode==='speed'?'selected':''}>스피드 · 5초</option><option value="item" ${state.settings.wordchainMode==='item'?'selected':''}>아이템 모드</option></select></label><label>턴 시간<select id="sWTime"><option value="5" ${state.settings.wordchainTurnTime==5?'selected':''}>5초</option><option value="7" ${state.settings.wordchainTurnTime==7?'selected':''}>7초</option><option value="10" ${state.settings.wordchainTurnTime==10?'selected':''}>10초</option><option value="15" ${state.settings.wordchainTurnTime==15?'selected':''}>15초</option><option value="20" ${state.settings.wordchainTurnTime==20?'selected':''}>20초</option></select></label><label>목숨<select id="sWLives"><option value="1" ${state.settings.wordchainLives==1?'selected':''}>1개</option><option value="2" ${state.settings.wordchainLives==2?'selected':''}>2개</option><option value="3" ${state.settings.wordchainLives==3?'selected':''}>3개</option><option value="5" ${state.settings.wordchainLives==5?'selected':''}>5개</option></select></label><label>한방단어<select id="sWOne"><option value="0" ${!state.settings.wordchainOneShot?'selected':''}>허용 · 공격 가능</option><option value="1" ${state.settings.wordchainOneShot?'selected':''}>금지 · 매너 모드</option></select></label><div class="wordchain-rule-note">🇰🇷 두음법칙은 기본 적용됩니다.</div>`;
 if(['liar','mafia'].includes(state.game))h+=`<label>진행 시간<select id="sRound"><option value="0" ${!state.settings.roundTime?'selected':''}>제한없음</option><option value="60" ${state.settings.roundTime==60?'selected':''}>60초</option><option value="120" ${state.settings.roundTime==120?'selected':''}>120초</option><option value="180" ${state.settings.roundTime==180?'selected':''}>180초</option><option value="300" ${state.settings.roundTime==300?'selected':''}>300초</option></select></label><label>투표 시간<select id="sVote"><option value="20" ${state.settings.voteTime==20?'selected':''}>20초</option><option value="30" ${state.settings.voteTime==30?'selected':''}>30초</option><option value="60" ${state.settings.voteTime==60?'selected':''}>60초</option></select></label>`;
 if(state.game==='rummi')h+=`<label>한 사람 턴 시간<select id="sRummiTime"><option value="45" ${state.settings.rummiTurnTime==45?'selected':''}>45초</option><option value="60" ${state.settings.rummiTurnTime==60?'selected':''}>60초</option><option value="90" ${state.settings.rummiTurnTime==90?'selected':''}>90초</option><option value="120" ${state.settings.rummiTurnTime==120?'selected':''}>120초</option></select></label>`;
 h+='</div><button id="save" class="primary">설정 저장</button>';e.innerHTML=h;
 if($('#sGame'))$('#sGame').onchange=()=>{if($('#sGame').value!==state.game)socket.emit('switchGame',{game:$('#sGame').value},r=>{if(!r.ok)toast(r.error)})};
 if($('#sGeniusGame'))$('#sGeniusGame').onchange=()=>socket.emit('updateSettings',{geniusGame:$('#sGeniusGame').value},r=>!r.ok&&toast(r.error));
 if($('#sMode'))$('#sMode').onchange=()=>socket.emit('updateSettings',{mode:$('#sMode').value},r=>!r.ok&&toast(r.error));
 $('#save').onclick=()=>{const d={};if($('#sMode'))d.mode=$('#sMode').value;if($('#sRoleMode'))d.liarRoleMode=$('#sRoleMode').value;if($('#sLiar'))d.liarCount=+$('#sLiar').value;if($('#sLiarMatch'))d.liarMatch=$('#sLiarMatch').value;if($('#sLiarTalk'))d.liarTalkTime=+$('#sLiarTalk').value;if($('#sTruth'))d.truthLevel=$('#sTruth').value;if($('#sRound'))d.roundTime=+$('#sRound').value;if($('#sVote'))d.voteTime=+$('#sVote').value;if($('#sRummiTime'))d.rummiTurnTime=+$('#sRummiTime').value;if($('#sWMode'))d.wordchainMode=$('#sWMode').value;if($('#sWTime'))d.wordchainTurnTime=+$('#sWTime').value;if($('#sWLives'))d.wordchainLives=+$('#sWLives').value;if($('#sWOne'))d.wordchainOneShot=$('#sWOne').value==='1';if($('#sGeniusGame'))d.geniusGame=$('#sGeniusGame').value;if($('#sDeathmatchGame'))d.deathmatchGame=$('#sDeathmatchGame').value;if($('#sDeathmatchBet'))d.deathmatchGarnetBet=+$('#sDeathmatchBet').value;if($('#sGarnetMatch'))d.stockGarnetMatch=$('#sGarnetMatch').value==='1';if($('#sRankHidden'))d.stockRankHidden=$('#sRankHidden').value==='1';socket.emit('updateSettings',d,r=>toast(r.ok?'설정을 저장했습니다.':r.error))}
}
function renderHost(){const e=$('#hostControls');let buttons='';if(state.phase==='lobby'){buttons='<button id="mainHome" class="ghost">메인화면</button>';if(host())buttons+='<button id="start" class="primary compact">게임 시작</button>';}else if(host()&&state.game==='liar'&&['play','reveal','liarDefense'].includes(state.phase))buttons='<button id="openVote">투표 시작</button>';else if(host()&&state.game==='mafia'&&state.phase==='mafiaDay')buttons='<button id="openVote">낮 투표 시작</button>';else if(host()&&state.game==='truth'&&state.phase==='truth')buttons='<button id="reroll">다른 질문</button><button id="next" class="primary compact">다음 사람</button>';else if(host()&&['result','mafiaResult','rummiResult','wordchainResult','forgeryFinal','crocodileResult','telepathyFinal','stockFinal','zombieResult','smugglingFinal'].includes(state.phase))buttons='<button id="lobby">대기실</button><button id="next" class="primary compact">한 판 더</button>';if(host()&&state.phase!=='lobby')buttons+='<button id="endGame" class="danger compact">게임 종료</button>';e.innerHTML=buttons;if($('#mainHome'))$('#mainHome').onclick=()=>{if(host()&&!confirm('방장이 메인화면으로 나가면 방이 종료됩니다. 나갈까요?'))return;socket.emit('leaveRoom',{},()=>home())};if($('#start'))$('#start').onclick=()=>{unlockStockBgm();socket.emit('startGame',{},r=>!r.ok&&toast(r.error))};if($('#openVote'))$('#openVote').onclick=()=>socket.emit('openVoting',{},r=>!r.ok&&toast(r.error));if($('#reroll'))$('#reroll').onclick=()=>socket.emit('truthReroll',{});if($('#next'))$('#next').onclick=()=>socket.emit('nextRound',{});if($('#lobby'))$('#lobby').onclick=()=>socket.emit('backToLobby',{});if($('#endGame'))$('#endGame').onclick=()=>{if(confirm('현재 게임을 완전히 종료하고 대기실로 돌아갈까요?'))socket.emit('endGame',{},r=>!r.ok&&toast(r.error))}}

function renderGame(){if(state.phase==='lobby'){const desc={liar:'단어 게임 / 질문 게임 중에서 선택해 플레이할 수 있습니다.',mafia:'밤의 능력과 낮 투표로 마피아를 찾아내세요.',rummi:'14개 타일로 시작해 유효한 조합을 만들어 먼저 패를 비우세요.',wordchain:'순서대로 단어를 이어 목숨을 지키고 마지막까지 살아남으세요.',forgery:'비슷한 제시어를 받은 한 명의 위조범을 그림만 보고 찾아내세요.',crocodile:'이빨을 하나씩 누르세요. 악어에게 물리지 않고 마지막까지 살아남으세요.',telepathy:'친구들과 같은 답을 떠올리세요. 청개구리 라운드에서는 반대로 혼자 다른 답을 노리세요.',genius:'전략·협상·심리전 게임을 이 방에서 선택해 플레이합니다.',stockwar:'정보는 무기가 되고, 협상은 기회가 됩니다. 시장과 사람을 읽어 8번의 승부 끝에 최고의 자산가가 되십시오.',smuggling:'가방의 진실을 숨기고 세관원을 설득해 가장 많은 자산을 만드세요.'}[state.game];const n=state.players.filter(p=>p.connected).length;const geniusLobby=state.game==='genius'?`<div class="genius-lobby-head"><div class="eyebrow">GENIUS GAME LOBBY</div><h2>플레이할 게임을 선택하세요</h2><p>${host()?'방장이 게임을 선택한 뒤 게임 시작을 누르면 됩니다.':'방장이 게임을 선택하는 중입니다.'}</p></div><div class="genius-game-selector-view"><button class="genius-mini-game ${state.settings.geniusGame==='stockwar'?'selected':''}" data-genius-pick="stockwar" ${host()?'':'disabled'}><b>📈 주식전쟁</b><span>약 40분</span><p>정보·협상·투자로 8라운드 시장을 지배하세요.</p></button><button class="genius-mini-game ${state.settings.geniusGame==='zombie'?'selected':''}" data-genius-pick="zombie" ${host()?'':'disabled'}><b>🧟 좀비게임</b><span>약 25분</span><p>감염 여부를 알 수 없는 접촉과 심리전.</p></button><button class="genius-mini-game ${state.settings.geniusGame==='smuggling'?'selected':''}" data-genius-pick="smuggling" ${host()?'':'disabled'}><b>🧳 밀수</b><span>약 35분</span><p>가방·허위 신고·뇌물·세관 검사로 벌이는 블러핑 협상전.</p></button></div>`:'';$('#mainCard').innerHTML=`<div class="big">${labels[state.game]}</div><p>${desc||''}</p><p>현재 ${n}명 · ${mins[state.game]}~${maxes[state.game]}명 플레이</p>${state.game==='mafia'?`<div class="mafia-composition"><b>이번 인원 기준 직업</b><div>${mafiaRoleSummary(n)}</div></div>`:''}${geniusLobby}`;$('#actionArea').innerHTML='';if(state.game==='genius'){$$('[data-genius-pick]').forEach(b=>b.onclick=()=>socket.emit('updateSettings',{geniusGame:b.dataset.geniusPick},r=>!r.ok&&toast(r.error)))}return}if(state.game==='liar')renderLiar();else if(state.game==='mafia')renderMafia();else if(state.game==='rummi')renderRummi();else if(state.game==='wordchain')renderWordchain();else if(state.game==='forgery')renderForgery();else if(state.game==='crocodile')renderCrocodile();else if(state.game==='telepathy')renderTelepathy();else if(state.game==='stockwar')renderStockwar();else if(state.game==='zombie')renderZombie();else if(state.game==='smuggling')renderSmuggling()}
function voteUI(e,ps){const tie=state.game==='liar'?(state.liarTieCandidates||[]):[];const eligible=ps.filter(p=>p.id!==me&&p.connected&&(state.game!=='mafia'||p.alive)&&(!tie.length||tie.includes(p.id))),total=state.game==='mafia'?state.players.filter(p=>p.connected&&p.alive).length:state.players.filter(p=>p.connected).length;const progress=`<div class="vote-progress">🗳️ 투표 ${state.votesSubmitted.length}/${total}</div>`;if(state.votesSubmitted.includes(me)){e.innerHTML=progress+'<p>투표 완료! 다른 플레이어를 기다리는 중…</p>';return}e.innerHTML=progress+'<h3>한 명을 선택하세요</h3><div class="vote-grid">'+eligible.map(p=>`<button class="vote-btn" data-id="${p.id}"><span class="face">${avatarHtml(p.avatar)}</span>${esc(p.name)}</button>`).join('')+'</div>';e.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>socket.emit('vote',{targetId:b.dataset.id},r=>!r.ok&&toast(r.error)))}
function renderLiar(){const c=$('#mainCard'),a=$('#actionArea');if(!priv)return;const fool=priv.roleMode==='fool'||priv.roleMode==='spy';
if(state.mode==='normal'){if(fool)c.innerHTML=`<div class="eyebrow">카테고리 · ${esc(priv.category)}</div><div class="big pop">${esc(priv.word||'')}</div><p class="muted">모두 자신의 제시어만 확인할 수 있습니다.</p>`;else{const roleLabel=priv.isLiar?'🤫 라이어':'✅ 시민';c.innerHTML=`<div class="eyebrow">카테고리 · ${esc(priv.category)}</div><div class="big ${priv.isLiar?'liar':''}">${roleLabel}</div>${priv.word?`<div class="big pop">${esc(priv.word)}</div>`:'<p>제시어를 모릅니다. 카테고리와 대화를 잘 활용하세요.</p>'}`}}else c.innerHTML=priv.isLiar?`<div class="big liar">🤫 라이어</div><p>질문은 비밀입니다.</p><div class="big">범위 ${priv.min}~${priv.max}</div>`:`<div class="big question">${esc(priv.question)}</div><p>숫자 범위 ${priv.min}~${priv.max}</p>`;
if(state.phase==='liarTalk'){const order=state.liarTalkOrder||[],cur=state.players.find(p=>p.id===order[state.liarTalkIndex]),mine=cur?.id===me;a.innerHTML=`<div class="liar-talk-stage"><div class="eyebrow">ROUND ${state.round} · 순차 발언 ${Math.min(state.liarTalkIndex+1,order.length)}/${order.length}</div><h2>🎤 ${esc(cur?.name||'플레이어')}님의 설명 차례</h2><div class="liar-talk-order">${order.map((id,i)=>{const p=state.players.find(x=>x.id===id);return `<span class="${i===state.liarTalkIndex?'active':i<state.liarTalkIndex?'done':''}">${p?avatarHtml(p.avatar,'mini-avatar'):''}${esc(p?.name||'')}</span>`}).join('<b>›</b>')}</div><p>${mine?'제시어를 직접 말하지 말고 적당히 설명하세요.':'현재 발언자의 설명을 잘 들어보세요.'}</p>${mine?'<button id="liarTalkDone" class="primary">설명 완료</button>':''}</div>`;$('#liarTalkDone')?.addEventListener('click',()=>socket.emit('liarSpeakerDone',{},r=>!r.ok&&toast(r.error)));return}
if(state.phase==='play'&&state.mode==='normal'){a.innerHTML=`<div class="result"><h3>💬 자유 토론</h3><p>모든 설명이 끝났습니다. 의심되는 사람을 토론하세요.</p><p class="muted">방장은 준비되면 투표를 시작할 수 있습니다.</p></div>`}
if(state.mode==='question'&&state.phase==='play'&&!state.submitted.includes(me)){a.innerHTML=`<div class="join"><input id="ans" type="number" min="${priv.min}" max="${priv.max}" placeholder="${priv.min}~${priv.max}"><button id="ansBtn">답변</button></div><p class="muted">모두 제출하면 답변이 동시에 공개됩니다.</p>`;$('#ansBtn').onclick=()=>socket.emit('submitAnswer',{value:$('#ans').value},r=>!r.ok&&toast(r.error))}else if(state.answersRevealed&&state.phase==='reveal'){a.innerHTML='<h3>📊 모두의 답변</h3>'+state.players.map(p=>`<div class="answer-card"><span>${avatarHtml(p.avatar,'mini-avatar')} ${esc(p.name)}</span><b>${state.answers[p.id]??'미제출'}</b></div>`).join('')}
if(state.phase==='liarDefense'){const ids=state.liarTieCandidates||[];a.innerHTML=`<div class="result warning"><div class="eyebrow">동률 발생</div><h2>⚠️ 최후 변론 30초</h2><p>${ids.map(id=>esc(state.players.find(p=>p.id===id)?.name||'')).join(' VS ')}</p><p>후보들의 마지막 변론을 들은 뒤 재투표합니다.</p></div>`;return}
if(state.phase==='vote')voteUI(a,state.players);
if(state.phase==='liarCaught')a.innerHTML='<div class="result"><h2>🎯 라이어를 맞혔습니다!</h2><p>잠시 후 라이어에게 마지막 정답 추측 기회가 주어집니다.</p></div>';
if(state.phase==='liarGuess'){a.innerHTML=priv.canGuess?`<div class="result warning"><h2>🤔 마지막 정답 추측</h2><p>💡 정답은 <b>${priv.wordLength}글자</b>입니다.</p><div class="join"><input id="guess" autocomplete="off"><button id="guessBtn">정답 제출</button></div></div>`:'<div class="result"><h2>🧠 라이어가 정답을 추측 중입니다…</h2><p>25초 안에 시민의 제시어를 맞히면 보너스를 얻습니다.</p></div>';$('#guessBtn')?.addEventListener('click',()=>socket.emit('submitLiarGuess',{guess:$('#guess').value},r=>!r.ok&&toast(r.error)))}
if(state.phase==='result'){const names=state.voteResult?.liarIds.map(id=>state.players.find(p=>p.id===id)?.name).filter(Boolean).join(', '),isFool=state.voteResult?.roleMode==='fool'||state.voteResult?.roleMode==='spy',maxRound=state.settings.liarMatch==='1'?1:5,final=state.round>=maxRound;a.innerHTML=`<div class="result liar-reveal"><div class="eyebrow">${final?'MATCH RESULT':`ROUND ${state.round} RESULT`}</div><h2>${state.voteResult?.caught?'🎉 지목 성공!':'😈 지목 실패!'}</h2><p>${isFool?'바보':'라이어'}: <b>${esc(names||'')}</b></p>${isFool?`<p>시민 제시어 <b>${esc(state.voteResult.citizenWord||'')}</b> · 바보 제시어 <b>${esc(state.voteResult.spyWord||'')}</b></p>`:state.voteResult?.citizenWord?`<p>정답 <b>${esc(state.voteResult.citizenWord)}</b></p>`:''}<div class="liar-scoreboard">${state.players.slice().sort((x,y)=>y.score-x.score).map((p,i)=>`<div><span>${i+1}위 · ${avatarHtml(p.avatar,'mini-avatar')} ${esc(p.name)}</span><b>${p.score}점</b></div>`).join('')}</div>${!final&&maxRound>1?`<p class="muted">${state.round} / ${maxRound} 라운드 완료</p>`:''}</div>`}}
function renderTruth(){const turn=state.players.find(p=>p.id===state.truthTurnId);$('#mainCard').innerHTML=`<div class="eyebrow">${(state.settings.truthLevel||'normal').toUpperCase()}</div><div class="big">${turn?avatarHtml(turn.avatar,'mini-avatar'):''} ${esc(turn?.name||'')}님의 차례</div><div class="big question">${esc(state.truthQuestion)}</div>`;$('#actionArea').innerHTML='<p class="muted">디스코드에서 솔직하게 답해주세요. 불편한 질문은 방장이 다른 질문으로 넘길 수 있습니다.</p>'}
function mafiaChatBox(){if(!priv)return '';let title='',msgs=[];if(!priv.alive){title='💀 사망자 비밀 채팅';msgs=priv.deadChat||[]}else if(['mafia','spy'].includes(priv.role)&&(priv.mafiaTeamIds||[]).length>=2){title='🔒 마피아팀 비밀 채팅';msgs=priv.teamChat||[]}else return '';return `<div class="mafia-chat ${title.includes('마피아팀')?'mafia-team-chat':''}"><b>${title}</b><div class="mafia-chat-log">${msgs.map(m=>`<div><strong>${esc(m.name)}</strong> ${esc(m.text)}</div>`).join('')||'<span class="muted">아직 메시지가 없습니다.</span>'}</div><div class="mafia-chat-send"><input id="mafiaChatInput" maxlength="120" placeholder="비밀 메시지"><button id="mafiaChatSend">전송</button></div></div>`}
