function zombieRulePages(){return [
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 1 / 6 · ZOMBIE GAME</div><h2>좀비게임</h2><p class="rule-lead">믿을 사람을 선택해 접촉하십시오. 하지만 <b>누가 감염됐는지는 아무도 확신할 수 없습니다.</b></p><div class="rule-columns two"><div><strong>6~7명</strong><p>최초 좀비 1명</p></div><div><strong>8~10명</strong><p>최초 좀비 2명</p></div></div><div class="rule-callout">총 3라운드 · 1R 6분 / 2R 6분 / FINAL 7분</div></div>`,
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 2 / 6 · CONTACT</div><h2>접촉은 반드시 서로 동의해야 합니다</h2><div class="rule-columns two"><div><strong>인간 × 인간</strong><p>두 사람 모두 승점 +1</p></div><div><strong>인간 × 좀비</strong><p>인간이 감염됩니다. 단, 감염 여부는 알려주지 않습니다.</p></div></div><div class="rule-note">좀비 × 좀비는 아무 일도 일어나지 않습니다. 한 번 접촉한 상대와는 게임이 끝날 때까지 다시 접촉할 수 없습니다.</div></div>`,
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 3 / 6 · LIMIT</div><h2>누구를 믿을지 선택하십시오</h2><div class="rule-columns two"><div><strong>1·2라운드</strong><p>한 사람당 최대 2명과 접촉</p></div><div><strong>FINAL</strong><p>단 한 명과만 접촉</p></div></div><div class="rule-note danger">라운드 동안 단 한 번도 접촉하지 않은 인간은 라운드 종료와 함께 감염됩니다.</div></div>`,
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 4 / 6 · UNKNOWN</div><h2>감염 여부는 끝까지 비공개</h2><p class="rule-lead">접촉 직후에도 내 상태는 알려주지 않습니다. 인간이었다고 믿었던 사람이 이미 감염됐을 수도 있습니다.</p><div class="rule-callout">라운드 종료 시 공개되는 정보는 오직 <b>인간 N명 / 좀비 N명</b>뿐입니다.</div></div>`,
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 5 / 6 · CURE</div><h2>치료제는 단 한 번</h2><p class="rule-lead">모든 플레이어는 치료제 1개를 가집니다. 감염 후 <b>5분 이내</b> 사용했다면 인간으로 회복합니다.</p><div class="rule-columns two"><div><strong>상태 확인 불가</strong><p>감염 여부와 치료 가능시간 카운트는 표시되지 않습니다.</p></div><div><strong>사용 결과 비공개</strong><p>인간일 때 사용하거나 최초 좀비가 사용해도 소비되며 효과 여부는 알려주지 않습니다.</p></div></div></div>`,
`<div class="stock-rule-page ppt zombie-ppt"><div class="rule-kicker">PAGE 6 / 6 · VICTORY</div><h2>끝까지 인간으로 남으십시오</h2><p class="rule-lead">생존 인간이 있다면 생존 인간끼리 승점으로 순위를 정합니다. 모두 감염되면 최초 좀비가 승리합니다.</p><div class="rule-columns two"><div><strong>대화</strong><p>음성대화는 디스코드, 밀담은 게임 내 1:1 비밀대화를 사용합니다.</p></div><div><strong>FINAL</strong><p>접촉 기회는 단 1회. 마지막 선택이 생존을 결정합니다.</p></div></div></div>`]}
function zombieRules(){return `<div class="zombie-rules"><h2>좀비게임 핵심 규칙</h2><p><b>감염 여부는 게임 중 확인할 수 없습니다. 사람의 말과 라운드별 인원 변화로 추리하십시오.</b></p><div class="zrule-grid"><div><strong>시간</strong><p>1R 6분 · 2R 6분 · FINAL 7분</p></div><div><strong>접촉</strong><p>1·2R 최대 2명, FINAL 최대 1명. 같은 상대와는 게임 중 한 번만 가능합니다.</p></div><div><strong>승점</strong><p>접촉 당시 인간끼리였다면 양쪽 +1점. 점수 획득 여부는 즉시 알려주지 않습니다.</p></div><div><strong>의무 접촉</strong><p>접촉 0회의 인간은 라운드 종료 시 감염됩니다.</p></div><div><strong>치료제</strong><p>1개 보유. 감염 후 5분 이내 사용 시 치료되지만 감염 여부·남은 시간·효과는 공개되지 않습니다.</p></div><div><strong>대화</strong><p>음성은 디스코드, 밀담은 게임 내 1:1 비밀대화를 이용합니다. 거짓말과 블러핑이 허용됩니다.</p></div></div></div>`}
function openZombieWhisper(targetId){zombieChatTarget=targetId;const p=state.players.find(x=>x.id===targetId);if(!p)return;const incoming=(priv?.messages||[]).filter(m=>!m.own&&m.from===targetId).length;zombieReadCounts[targetId]=incoming;$('#zombieWhisperTitle').textContent=`${p.name} · 비밀 대화`;renderZombieWhisper();$('#zombieWhisperModal').classList.remove('hidden');renderPlayers();setTimeout(()=>$('#zombieWhisperInput')?.focus(),30)}
function renderZombieWhisper(){if(!zombieChatTarget)return;const msgs=(priv?.messages||[]).filter(m=>m.from===zombieChatTarget||m.to===zombieChatTarget);$('#zombieWhisperHistory').innerHTML=msgs.map(m=>`<div class="stock-chat-row ${m.own?'mine':'theirs'}"><div class="stock-chat-bubble"><b>${m.own?'나':esc(m.name)}&nbsp;</b><span>${esc(m.text)}</span></div></div>`).join('')||'<span class="muted">아직 대화가 없습니다.</span>';const x=$('#zombieWhisperHistory');if(x)x.scrollTop=x.scrollHeight}
function sendZombieWhisper(){const text=$('#zombieWhisperInput')?.value.trim();if(!zombieChatTarget||!text)return;socket.emit('zombieWhisper',{targetId:zombieChatTarget,text},r=>{if(!r.ok)return toast(r.error);$('#zombieWhisperInput').value='';setTimeout(renderZombieWhisper,80)})}
let zombieRulePage=0;
function renderZombie(){const z=state.zombie,c=$('#mainCard'),a=$('#actionArea');if(!z)return;syncZombieAudio();syncSmugglingAudio();syncGeniusEndingAudio();const pd=priv?.game==='zombie'?priv:null,report=z.lastReport,touchCount=pd?.touchesThisRound?.length||0,limit=pd?.touchLimit||(z.round===3?1:2);if(state.phase==='zombieBriefing'){const pages=zombieRulePages(),ready=z.briefingReady?.includes?.(me),readyCount=z.briefingReady?.length||0,total=state.players.filter(p=>p.connected&&!p.isBot).length;c.innerHTML=pages[zombieRulePage];a.innerHTML=`<div class="rule-nav"><button id="zRulePrev" ${zombieRulePage===0?'disabled':''}>이전</button><span>${zombieRulePage+1} / ${pages.length}</span><button id="zRuleNext" ${zombieRulePage===pages.length-1?'disabled':''}>다음</button></div>${zombieRulePage===pages.length-1?`<div class="briefing-ready"><b>준비 완료 ${readyCount}/${total}</b><button id="zBriefReady" class="primary" ${ready?'disabled':''}>${ready?'준비 완료':'룰 확인 완료'}</button><p class="muted">전원이 누르면 즉시 시작 · 최대 3분 후 자동 시작</p></div>`:''}`;$('#zRulePrev')?.addEventListener('click',()=>{zombieRulePage=Math.max(0,zombieRulePage-1);renderZombie()});$('#zRuleNext')?.addEventListener('click',()=>{zombieRulePage=Math.min(pages.length-1,zombieRulePage+1);renderZombie()});$('#zBriefReady')?.addEventListener('click',()=>socket.emit('zombieBriefingReady',{},r=>!r.ok&&toast(r.error)));return}
 if(state.phase==='zombieRole'){const original=pd?.originalZombie;c.innerHTML=`<div class="zombie-stage role"><div class="zombie-kicker">비밀 역할</div><h1>${original?'최초 좀비':'인간'}</h1><p>${original?'당신은 최초 좀비입니다. 정체를 숨기고 인간을 감염시키십시오.':'당신은 인간으로 시작합니다. 이후 감염 여부는 알려주지 않습니다.'}</p></div>`;a.innerHTML=zombieRules();return}
 if(state.phase==='zombieResult'){c.innerHTML=`<div class="zombie-stage result"><div class="zombie-kicker">게임 종료</div><h1>${z.result?.humans?'인간 생존':'최초 좀비 승리'}</h1><p>인간 ${z.result?.humans||0}명 · 좀비 ${z.result?.zombies||0}명</p></div>`;a.innerHTML=`<div class="zombie-result-list">${(z.result?.ranking||[]).map((x,i)=>`<div><b>${i+1}위 · ${esc(x.name)}</b><span>${x.originalZombie?'최초 좀비':x.status==='human'?'인간 생존':'감염'} · ${x.points}점</span></div>`).join('')}</div>`;return}
 c.innerHTML=`<div class="zombie-stage"><div class="zombie-kicker">${state.phase==='zombieReport'?'감염 현황':`${z.round}라운드 / 3라운드`}</div><h1>${state.phase==='zombieReport'?(report?`인간 ${report.humans}명 · 좀비 ${report.zombies}명`:'현황 확인 중'):'좀비게임'}</h1><p>${esc(z.message||'')}</p>${report&&state.phase==='zombiePlay'?`<div class="zombie-last-report">직전 현황 · 인간 ${report.humans}명 / 좀비 ${report.zombies}명</div>`:''}</div>`;const incoming=pd?.pendingIncoming||[];a.innerHTML=`${incoming.map(q=>`<div class="zombie-touch-request"><b>${esc(q.fromName)}님이 접촉을 요청했습니다.</b><div><button data-zaccept="${q.id}" class="primary">수락</button><button data-zreject="${q.id}">거절</button></div></div>`).join('')}<div class="zombie-dashboard"><section><small>내 최초 역할</small><strong>${pd?.originalZombie?'최초 좀비':'인간'}</strong></section><section><small>현재 감염 여부</small><strong class="unknown-status">확인 불가</strong></section><section><small>승점</small><strong>${pd?.points||0}점</strong></section><section><small>치료제</small><strong>${pd?.cure||0}개</strong></section><section><small>이번 라운드 접촉</small><strong>${touchCount} / ${limit}${state.phase==='zombiePlay'&&!touchCount?' ⚠️':''}</strong></section></div>${pd?.cure&&state.phase==='zombiePlay'?`<button id="zombieCure" class="zombie-cure">치료제 사용</button><p class="muted zombie-cure-note">감염 여부와 치료 가능시간은 표시되지 않습니다. 사용 결과도 공개되지 않습니다.</p>`:''}<details class="zombie-rule-details"><summary>상세 규칙 보기</summary>${zombieRules()}</details>`;$$('[data-zaccept]').forEach(b=>b.onclick=()=>socket.emit('zombieTouchRespond',{requestId:b.dataset.zaccept,accept:true},r=>toast(r.ok?'접촉이 완료되었습니다. 감염 여부는 공개되지 않습니다.':r.error)));$$('[data-zreject]').forEach(b=>b.onclick=()=>socket.emit('zombieTouchRespond',{requestId:b.dataset.zreject,accept:false},r=>toast(r.ok?'접촉을 거절했습니다.':r.error)));if($('#zombieCure'))$('#zombieCure').onclick=()=>{if(confirm('치료제를 사용하시겠습니까?\n현재 감염 여부와 치료 효과는 알려주지 않습니다.'))socket.emit('zombieCure',{},r=>toast(r.ok?r.message:r.error))};bindZombiePlayerActions()}
const stockBgm=new Audio('/stock-war-music-v34.mp3');
stockBgm.loop=true;stockBgm.preload='auto';stockBgm.playsInline=true;stockBgm.volume=.10;
let stockBgmUnlocked=false,stockBgmRetry=null,lastDealer='';
// One-time migration: this build intentionally starts Stock War BGM ON at 10%.
if(localStorage.sosoStockBgmInitV34!=='1'){localStorage.sosoStockBgmInitV34='1';localStorage.sosoBgm='on';localStorage.sosoBgmVolume='10';bgmOn=true}
function stockBgmWanted(){return !!(bgmOn&&state?.game==='stockwar'&&state.phase!=='lobby')}
async function unlockStockBgm(){
  if(stockBgmUnlocked)return true;
  const prevMuted=stockBgm.muted,prevVol=stockBgm.volume;
  try{
    stockBgm.muted=true;stockBgm.volume=0;
    await stockBgm.play();
    stockBgmUnlocked=true;
    if(!stockBgmWanted()){stockBgm.pause();try{stockBgm.currentTime=0}catch{}}
    stockBgm.muted=prevMuted;stockBgm.volume=bgmVolume();
    return true;
  }catch(err){
    stockBgm.muted=prevMuted;stockBgm.volume=prevVol;
    return false;
  }
}
function ensureStockBgm(){
  clearTimeout(stockBgmRetry);
  stockBgm.muted=false;stockBgm.volume=bgmVolume();
  if(!stockBgmWanted()){stockBgm.pause();return}
  const attempt=()=>{
    stockBgm.muted=false;stockBgm.volume=bgmVolume();
    stockBgm.play().then(()=>{stockBgmUnlocked=true}).catch(()=>{stockBgmRetry=setTimeout(attempt,1200)});
  };
  attempt();
}
// Any normal click/tap/key press unlocks browser audio permission for later Stock War playback.
document.addEventListener('pointerdown',()=>{if(!stockBgmUnlocked)unlockStockBgm()},{capture:true,passive:true});
document.addEventListener('keydown',()=>{if(!stockBgmUnlocked)unlockStockBgm()},{capture:true});
stockBgm.addEventListener('error',()=>console.warn('Stock War BGM load error',stockBgm.error));
function speakDealer(text,done){if(!text||!narrationOn){done?.();return}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang?.toLowerCase().startsWith('ko')&&/natural|neural|sunhi|injoon|google|microsoft/i.test(v.name))||voices.find(v=>v.lang?.toLowerCase().startsWith('ko'))||null;u.rate=1.5;u.pitch=1.0;u.volume=narrationVolume();u.onend=u.onerror=()=>done?.();speechSynthesis.speak(u)}catch{done?.()}}
function syncStockAudio(){
  const v=bgmVolume();stockBgm.volume=v;
  ensureStockBgm();
  if(state?.game==='stockwar'&&state.stock?.dealer&&state.stock.dealer!==lastDealer){
    lastDealer=state.stock.dealer;
    if(!stockBgm.paused)stockBgm.volume=Math.min(v,.015);
    speakDealer(lastDealer,()=>{stockBgm.volume=bgmVolume();ensureStockBgm()});
  }
}
function stockStars(n){return '★'.repeat(n||0)+'☆'.repeat(Math.max(0,5-(n||0)))}
function stockSpark(hist=[]){if(!hist.length)return'';const w=120,h=34,min=Math.min(...hist),max=Math.max(...hist),span=Math.max(1,max-min);const pts=hist.map((v,i)=>`${Math.round(i*(w/(Math.max(1,hist.length-1))))},${Math.round(h-(v-min)/span*h)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2"/></svg>`}
function stockStageText(){if(!state?.stock)return'';const r=state.stock.round||1,neg=r<=2?'2분 30초':r<=5?'2분 15초':r<=7?'2분':'2분 30초';const m={stockIntermission:'NEXT ROUND · 7초 후 다음 라운드가 시작됩니다.',stockInfoReview:'정보 확인 · 35초 — 흩어진 정보 조각과 시장 상황을 확인하세요.',stockNegotiation:`전략·협상 · ${neg} — 디스코드와 비밀대화로 정보를 조합하세요.`,stockAuction:'특급정보 경매 · 45초 — 보유 현금과 최고 입찰가를 확인하세요.',stockTrade:'MARKET OPEN · 1분 15초 — 순수 매수·매도세를 읽고 거래하세요.',stockResult:'결과 확인 · 20초 — 사건·등락률·수급을 다음 라운드 추리에 활용하세요.',stockBriefing:'룰 설명 — 모두 준비하면 시작합니다.'};return m[state.phase]||''}
function stockMemoKey(){return `sosoStockMemo:${state?.code||'room'}`}
function bindStockPlayerActions(){
 if(state?.game!=='stockwar')return;
 $$('[data-stock-chat]').forEach(b=>b.onclick=e=>{e.stopPropagation();openStockWhisper(b.dataset.stockChat,false)});
 $$('[data-stock-pay]').forEach(b=>b.onclick=e=>{e.stopPropagation();openStockWhisper(b.dataset.stockPay,true)});
}
function openStockWhisper(targetId,focusPay=false){
 if(state?.game!=='stockwar')return;stockChatTarget=targetId;const p=state.players.find(x=>x.id===targetId);if(!p)return;
 const incoming=(priv?.messages||[]).filter(m=>!m.own&&m.from===targetId).length;stockReadCounts[targetId]=incoming;
 $('#stockWhisperTitle').textContent=`${p.name} · 비밀 대화`;
 renderStockWhisperModal();$('#stockWhisperModal').classList.remove('hidden');setTimeout(()=>$(focusPay?'#stockTransferAmount':'#stockWhisperInput')?.focus(),30);renderPlayers()
}
function renderStockWhisperModal(){
 if(!stockChatTarget)return;const p=state.players.find(x=>x.id===stockChatTarget);if(!p)return;const msgs=(priv?.messages||[]).filter(m=>(m.from===stockChatTarget||m.to===stockChatTarget));
 $('#stockWhisperHistory').innerHTML=msgs.map(m=>`<div class="stock-chat-row ${m.own?'mine':'theirs'}"><div class="stock-chat-bubble"><b>${m.own?'나':esc(m.name)}&nbsp;</b><span>${esc(m.text)}</span>${m.card?'<small class="certified-info">✓ 시스템 인증 정보카드</small>':''}</div></div>`).join('')||'<span class="muted">아직 대화가 없습니다.</span>';
 const locked=state.phase==='stockTrade';$('#stockWhisperLock').classList.toggle('hidden',!locked);$('#stockWhisperInput').disabled=locked;$('#stockWhisperSend').disabled=locked;$('#stockWhisperInput').placeholder=locked?'시장 거래 중에는 비밀대화를 사용할 수 없습니다.':'비밀 메시지';
 const used=priv?.transferTo?.[stockChatTarget]||0,total=priv?.transferTotal||0;const box=$('#stockWhisperModal .stock-transfer-box small');if(box)box.textContent=`이번 라운드 송금 · 전체 ${total}/200C · ${p.name} ${used}/100C`;
 const h=$('#stockWhisperHistory');if(h)h.scrollTop=h.scrollHeight
}
function openStockShop(){renderStockShop();$('#stockShopModal').classList.remove('hidden')}
function renderStockShop(){const list=$('#stockShopList');if(!list)return;const offers=priv?.dealerOffers||[];list.innerHTML=offers.map(o=>`<div class="info-card"><small>${esc(o.grade)} · ${stockStars(o.stars||3)}</small><p><b>${esc(o.label||'시장 정보')}</b><br>내용은 구매 후 공개됩니다.</p><button class="compact" data-shop-buy="${o.id}" ${o.bought?'disabled':''}>${o.bought?'구매 완료':`${o.price}C로 구매`}</button></div>`).join('')||'<span class="muted">이번 라운드 판매 정보가 없습니다.</span>';$$('[data-shop-buy]').forEach(b=>b.onclick=()=>socket.emit('stockBuyDealerInfo',{offerId:b.dataset.shopBuy},r=>{toast(r.ok?'딜러 정보를 구매했습니다.':r.error);if(r.ok)setTimeout(renderStockShop,100)}))}
function stockRulePages(){return [
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 1 / 6 · STOCK WAR</div><h2>주식전쟁</h2><p class="rule-lead">흩어진 정보를 조합하고, 사람의 말을 판단하고, 시장에 투자해 <b>최고의 자산가</b>가 되십시오.</p><div class="rule-columns two"><div><strong>시작</strong><p>1,000C · 5개 기업 · 모든 주식 100C · 총 8라운드</p></div><div><strong>승리</strong><p><b>현금 + 보유주식 가치 - 부채</b>가 가장 높은 플레이어가 승리합니다.</p></div></div><div class="rule-callout">음성 협상은 디스코드를 이용하고, 게임 안에서는 1:1 비밀대화와 인증 정보카드를 사용할 수 있습니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 2 / 6 · ROUND</div><h2>빠르게 판단하십시오</h2><div class="rule-timeline"><div><b>01</b><strong>정보 확인 · 35초</strong><span>개인 정보와 시장 상황 확인</span></div><div><b>02</b><strong>전략·협상</strong><span>R1~2 2분30초 / R3~5 2분15초 / R6~7 2분 / FINAL 2분30초</span></div><div><b>03</b><strong>특급정보 경매 · 45초</strong><span>ROUND 3 · 6만 진행</span></div><div><b>04</b><strong>시장 거래 · 1분15초</strong><span>중간에 모두가 보는 시장 속보가 발생합니다.</span></div><div><b>05</b><strong>결과 확인 · 20초</strong><span>7초 준비 후 다음 라운드</span></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 3 / 6 · INFORMATION</div><h2>한 사람에게 정답은 없습니다</h2><p class="rule-lead">업종·방향·후보 기업·제외 정보·변동폭이 플레이어들에게 나뉘어 전달됩니다.</p><div class="rule-columns two"><div><strong>조각정보</strong><p>여러 사람의 정보를 합쳐야 핵심 기업과 방향을 정확히 좁힐 수 있습니다.</p></div><div><strong>시장소문</strong><p>일부 소문은 약 75%만 정확합니다. 소문은 반드시 다른 정보와 함께 판단하십시오.</p></div></div><div class="rule-note">인증 정보카드는 라운드당 한 번 다른 플레이어에게 원본 그대로 공유할 수 있습니다. 일반 채팅의 주장은 인증되지 않으며 거짓말이 가능합니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 4 / 6 · NEGOTIATION</div><h2>정보보다 사람을 읽으십시오</h2><div class="rule-columns two"><div><strong>협상</strong><p>디스코드와 1:1 비밀대화를 이용해 정보를 교환하고 동맹을 만들 수 있습니다.</p></div><div><strong>송금</strong><p>라운드당 총 200C, 같은 상대에게 최대 100C. 구두 약속은 시스템이 보장하지 않습니다.</p></div></div><div class="rule-note">딜러 정보상점은 정답 대신 추론 단서를 판매하며, 한 플레이어는 라운드당 1개만 구매할 수 있습니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 5 / 6 · MARKET</div><h2>행동이 시장을 움직입니다</h2><div class="rule-formula"><span>기업 사건</span><i>+</i><span>시장 상황</span><i>+</i><span>순수 매수·매도세</span><i>=</i><strong>주가 변동</strong></div><div class="rule-columns two"><div><strong>실시간 수급</strong><p>종목마다 매수 우위·매도 우위가 익명으로 표시됩니다. 같은 주식을 반복해서 사고팔아 거래량을 부풀려도 수급 영향은 증가하지 않습니다.</p></div><div><strong>중간 속보</strong><p>시장 도중 새로운 공개 단서가 등장합니다. 기존 판단을 유지할지 뒤집을지 결정하십시오.</p></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 6 / 6 · FINAL</div><h2>마지막 승부</h2><div class="rule-columns two"><div><strong>신용대출</strong><p>게임당 1회 · 최대 500C · 이자 20%. 사용 사실은 공개되지만 금액은 비공개입니다.</p></div><div><strong>FINAL</strong><p>마지막 협상은 2분30초. 별도의 운 보정 없이 지금까지 모은 정보와 관계, 자산으로 승부합니다.</p></div></div><div class="rule-note">개인미션은 없습니다. 오직 최종 순자산으로 승부합니다.<br>1위 💎3 / 2위 💎1 / 3위 💎1 · 1위는 꼴찌를 제외한 한 명에게 추가 💎1</div></div>`
]}
function stockDetailedRulePages(){return [...stockRulePages(),
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · INFORMATION</div><h2>딜러 상점과 경매</h2><p class="rule-lead">딜러 상점은 라운드당 1개만 구매할 수 있고 정답이 아닌 추론 단서를 판매합니다. 3·6라운드의 45초 경매에서는 더 강한 핵심 단서를 한 명이 독점합니다.</p></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · MARKET</div><h2>조작보다 판단</h2><p class="rule-lead">가격에 반영되는 수급은 거래 횟수가 아니라 라운드 시작 대비 실제 보유량 변화입니다.</p><div class="rule-note danger">따라서 같은 종목을 반복 매수·매도해 거래량만 늘려도 가격 영향은 누적되지 않습니다. 격동장은 정보로 어느 정도 예측할 수 있으며 무작위 반전은 제거됩니다.</div></div>`]}

function renderStockRuleSlide(page){const pages=stockRulePages();return pages[Math.max(0,Math.min(pages.length-1,page))]}
let stockRulesModalPage=0;
function openStockRules(page=0){stockRulesModalPage=page;renderStockRulesModal();$('#stockRulesModal')?.classList.remove('hidden')}
function renderStockRulesModal(){const pages=stockDetailedRulePages(),body=$('#stockRulesModalBody');if(!body)return;body.innerHTML=pages[stockRulesModalPage];$('#stockRulesPageLabel').textContent=`${stockRulesModalPage+1} / ${pages.length}`;$('#stockRulesPrev').disabled=stockRulesModalPage===0;$('#stockRulesNext').disabled=stockRulesModalPage===pages.length-1}
function renderStockSideTools(){const tools=$('#stockSideTools'),memo=$('#stockMemoSide');if(!tools||state?.game!=='stockwar'||state?.phase==='lobby'){tools?.classList.add('hidden');return}tools.classList.remove('hidden');if(memo&&document.activeElement!==memo){const saved=localStorage.getItem(stockMemoKey())||'';if(memo.value!==saved)memo.value=saved}}
function renderStockwar(){
 const st=state.stock;if(!st)return;syncStockAudio();const a=$('#actionArea'),c=$('#mainCard');
 if(state.phase==='stockBriefing'){
   window.stockRulePage=window.stockRulePage??0;const pages=stockRulePages(),pageCount=pages.length;
   const ready=(st.briefingReady||[]).includes(me),readyCount=(st.briefingReady||[]).filter(id=>state.players.some(p=>p.id===id&&!p.isBot)).length,total=state.players.filter(p=>p.connected&&!p.isBot).length;
   c.innerHTML=`<div class="stock-tutorial text-tutorial">${renderStockRuleSlide(window.stockRulePage)}</div>`;
   a.innerHTML=`<div class="rule-nav"><button id="rulePrev" ${window.stockRulePage===0?'disabled':''}>이전</button><span>${window.stockRulePage+1} / ${pageCount}</span><button id="ruleNext" ${window.stockRulePage===pageCount-1?'disabled':''}>다음</button></div>${window.stockRulePage===pageCount-1?`<div class="briefing-ready"><b>준비 완료 ${readyCount}/${total}</b><button id="briefReady" class="primary" ${ready?'disabled':''}>${ready?'준비 완료':'룰 확인 완료'}</button><p class="muted">전원이 누르면 즉시 시작 · 최대 3분 후 자동 시작</p></div>`:'<p class="muted rule-helper">핵심 규칙을 한 장씩 확인하세요.</p>'}`;
   if($('#rulePrev'))$('#rulePrev').onclick=()=>{window.stockRulePage=Math.max(0,window.stockRulePage-1);renderStockwar()};if($('#ruleNext'))$('#ruleNext').onclick=()=>{window.stockRulePage=Math.min(pageCount-1,window.stockRulePage+1);renderStockwar()};if($('#briefReady'))$('#briefReady').onclick=()=>socket.emit('stockBriefingReady',{},r=>!r.ok&&toast(r.error));return
 }
 if(state.phase==='stockIntermission'){c.innerHTML=`<div class="genius-intermission"><small>NEXT ROUND</small><h2>ROUND ${st.round+1} 준비</h2><p>7초 후 다음 라운드가 시작됩니다.</p></div>`;a.innerHTML='';return}
 const holdings=priv?.holdings||{},cash=priv?.cash??1000,info=priv?.info||[],contracts=priv?.contracts||[],mission=priv?.mission,debt=priv?.debt||0,netTotal=priv?.currentValue??Math.round(cash+st.companies.reduce((z,x)=>z+(holdings[x.id]||0)*x.price,0)-debt);
 const title=state.phase==='stockInfoReview'?'INFORMATION REVIEW':state.phase==='stockNegotiation'?'STRATEGY & NEGOTIATION':state.phase==='stockAuction'?'SPECIAL AUCTION':state.phase==='stockTrade'?'MARKET OPEN':state.phase==='stockFinal'?'FINAL MARKET':'MARKET NEWS';
 c.innerHTML=`<div class="stock-stage-banner"><b>${state.phase==='stockInfoReview'?'정보 확인 · 35초':state.phase==='stockNegotiation'?`전략·협상 · ${st.round<=2?'2분 30초':st.round<=5?'2분 15초':st.round<=7?'2분':'2분 30초'}`:state.phase==='stockAuction'?'특급정보 경매 · 45초':state.phase==='stockTrade'?'시장 거래 · 1분 15초':'결과 확인 · 20초'}</b><span>${state.phase==='stockTrade'?'매수·매도에 집중하세요. 대량 수급은 가격에 영향을 줍니다.':'상단 타이머와 현재 단계에 맞춰 행동하세요.'}</span></div><div class="stock-head"><div><span>ROUND ${st.round}/8</span><h2>${title}</h2></div><div class="stock-cash"><small>순자산</small> ${netTotal} C</div></div>
 <div class="stock-market-layout"><div class="stock-market-main"><div class="dealer-box">🎙️ <b>딜러</b> ${esc(st.dealer||'')}</div><div class="market-news">📰 ${esc(st.news||'')}</div>${st.marketEvent?`<div class="market-event">🌎 ${esc(st.marketEvent.text)} <b>${st.marketEvent.pct>0?'+':''}${st.marketEvent.pct}%</b></div>`:''}${[...(st.publicAlerts||[]),...(st.whaleAlerts||[])].length?`<div class="whale-feed">${[...(st.publicAlerts||[]),...(st.whaleAlerts||[])].slice(-6).map(x=>`<span>⚠ ${esc(x.text)}</span>`).join('')}</div>`:''}
 ${st.marketHistory?.length?`<div class="market-history-strip"><b>지난 시장 기록</b>${st.marketHistory.slice(-2).reverse().map(h=>`<span>R${h.round} · ${esc(h.event)} · ${h.rows.map(x=>`${esc(x.name)} ${x.change>=0?'+':''}${x.change}%/${esc(x.pulse)}`).join(' · ')}</span>`).join('')}</div>`:''}<div class="stock-grid">${st.companies.map(x=>{const vol=st.volume?.[x.id]||0;return `<div class="stock-card"><small>${esc(x.sector)}</small><b class="stock-company-name"><span class="stock-company-icon">${x.icon||'🏢'}</span>${esc(x.name)}</b><span class="stock-desc">${esc(x.desc||'')}</span><div class="trait-row"><span>안정 ${'●'.repeat(x.stability||0)}</span><span>성장 ${'●'.repeat(x.growth||0)}</span><span>변동 ${'●'.repeat(x.volatility||0)}</span></div><strong>${x.price}</strong><em class="${x.change>=0?'up':'down'}">${x.change>=0?'▲':'▼'} ${Math.abs(x.change||0)}%</em>${stockSpark(x.history||[])}<span>보유 ${holdings[x.id]||0}주 · 순수수급량 ${vol}</span><div class="market-pulse">${st.marketPulse?.[x.id]==='강한 매수세'?'🔥 ':st.marketPulse?.[x.id]==='강한 매도세'?'🔻 ':''}${esc(st.marketPulse?.[x.id]||'보통')}</div><div class="volume-bar"><i style="width:${Math.min(100,vol*6)}%"></i></div>${state.phase==='stockTrade'?`<div class="trade-row"><input data-qty="${x.id}" type="number" min="1" max="99" value="1"><button data-buy="${x.id}">매수</button><button data-sell="${x.id}">매도</button></div>`:''}</div>`}).join('')}</div></div></div>`;
 if(state.phase==='stockAuction'){
   const au=st.auction;a.innerHTML=`<div class="stock-auction"><div class="auction-lock">🔐</div><h2>특급정보 경매</h2><p>45초 동안 입찰합니다. 내용은 낙찰자에게만 공개됩니다.</p><div class="auction-cash">내 보유 현금 <b>${Math.round(cash)} C</b></div><div class="auction-bid">현재 최고가 <b>${au?.highBid||0} C</b><span>${esc(au?.highBidderName||'없음')}</span></div><div class="join"><input id="auctionAmount" type="number" min="1" placeholder="입찰 금액"><button id="auctionBid" class="primary">입찰</button></div></div>`;$('#auctionBid').onclick=()=>socket.emit('stockAuctionBid',{amount:+$('#auctionAmount').value},r=>!r.ok&&toast(r.error));return
 }
 if(state.phase==='stockFinalCounting'){c.innerHTML=`<div class="stock-final-counting"><div class="final-loader"></div><h2>게임 결과를 집계중입니다.</h2><p>최종 자산과 플레이 기록을 분석하고 있습니다.</p></div>`;a.innerHTML='';return}
 if(state.phase==='stockFinal'){
   const af=st.afterMarket||{};a.innerHTML=`<div class="result stock-final"><h2>8번의 장이 모두 끝났습니다.</h2><div class="final-ranking dramatic">${(st.ranking||[]).map((x,i)=>`<div class="rank-reveal rank-${i+1}" style="--delay:${i<3?i*1.05:3.15+(i-3)*.18}s"><b>${i+1}위 ${esc(x.name)}</b><strong>${x.value} C</strong></div>`).join('')}</div>${af.awards?.length?`<h3>게임 분석</h3><div class="after-awards">${af.awards.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}${af.rounds?.length?`<h3>진실 공개</h3><div class="truth-tape">${af.rounds.map(x=>`<div>R${x.round} · <b>${esc(x.company)}</b> · ${esc(x.event)} · ${x.pct>0?'+':''}${x.pct}%</div>`).join('')}</div>`:''}</div>`;return
 }
 const memo=localStorage.getItem(stockMemoKey())||'';
 a.innerHTML=`<div class="stock-bottom-grid">
 <section class="stock-console-card private-terminal"><div class="console-head"><span>PRIVATE TERMINAL</span><small>PERSONAL</small></div><div class="terminal-money"><span>현금 <b>${Math.round(cash)} C</b></span><span>순자산 <b>${netTotal} C</b></span><span>부채 <b>${debt} C</b></span><span>현재 순위 <b>${priv?.currentRank||'-'}위</b></span></div><div class="portfolio-mini">${st.companies.map(x=>(holdings[x.id]||0)>0?`<span>${esc(x.name)} ×${holdings[x.id]}</span>`:'').filter(Boolean).join('')||'<span class="muted">보유 주식 없음</span>'}</div><div class="terminal-buttons"><button id="openStockShop">딜러 정보상점</button><button id="stockLoanBtn" ${priv?.loanTaken?'disabled':''}>${priv?.loanTaken?'대출 사용 완료':'신용대출'}</button></div><small class="muted">송금 한도 · 라운드 ${priv?.transferTotal||0}/200C · 한 사람 최대 100C</small></section>
 <section class="stock-console-card stock-secret-section"><div class="console-head"><span>내 비밀정보</span><small>${info.length} CARDS</small></div><div class="info-list">${info.slice(-10).reverse().map(x=>`<div class="info-card"><small>${esc(x.grade)} · R${x.round} · ${esc(x.source||'정보원')}</small><div class="reliability">${stockStars(x.reliability||3)}</div><p>${esc(x.text)}</p>${x.dealerBought?'<b>딜러에게 직접 구매한 정보</b>':''}${['stockInfoReview','stockNegotiation','stockAuction','stockResult'].includes(state.phase)?`<button class="compact share-info-card" data-share-info="${x.id}">인증카드 공유</button>`:''}</div>`).join('')||'<span class="muted">개인 정보를 불러오는 중입니다.</span>'}</div></section>
 <section class="stock-console-card stock-deal-log"><div class="console-head"><span>협상 기록</span><small>LOG</small></div><p class="muted">플레이어의 말은 인증되지 않습니다.</p><div class="contract-log">${contracts.map(x=>`<div>${esc(x.text)}</div>`).join('')||'<span class="muted">아직 기록이 없습니다.</span>'}</div></section></div>`;
 $$('[data-buy]').forEach(b=>b.onclick=()=>{const q=Math.max(1,+document.querySelector(`[data-qty="${b.dataset.buy}"]`)?.value||1);socket.emit('stockTrade',{companyId:b.dataset.buy,side:'buy',qty:q},r=>!r.ok&&toast(r.error))});
 $$('[data-sell]').forEach(b=>b.onclick=()=>{const q=Math.max(1,+document.querySelector(`[data-qty="${b.dataset.sell}"]`)?.value||1);socket.emit('stockTrade',{companyId:b.dataset.sell,side:'sell',qty:q},r=>!r.ok&&toast(r.error))});
 $('#openStockShop')?.addEventListener('click',openStockShop);
 $$('[data-share-info]').forEach(b=>b.onclick=()=>{const choices=state.players.filter(p=>p.id!==me&&!p.isBot);const name=prompt('인증 정보카드를 공유할 플레이어 닉네임을 입력하세요.\n라운드당 1회만 공유할 수 있습니다.\n\n'+choices.map(p=>p.name).join(' / '));if(!name)return;const t=choices.find(p=>p.name===name.trim());if(!t)return toast('플레이어 닉네임을 정확히 입력해주세요.');socket.emit('stockShareInfo',{targetId:t.id,infoId:b.dataset.shareInfo},r=>toast(r.ok?'인증 정보카드를 공유했습니다.':r.error))});
 $('#stockLoanBtn')?.addEventListener('click',()=>{const raw=prompt('대출 금액을 입력하세요. (1~500C)\n게임당 1회 / 이자 20% / 최종 자동상환');if(raw===null)return;socket.emit('stockLoan',{amount:+raw},r=>toast(r.ok?`대출되었습니다. 최종 상환액 ${r.debt}C`:r.error))});
}
const SMITEM={goods:['📦','생활품'],perfume:['🧴','향수'],jewel:['💎','보석'],contraband:['☠️','밀수품']};let smSelected=[],smInspect=[];
function smItem(k){const x=SMITEM[k]||['❔',k];return `<span class="sm-item">${x[0]} ${x[1]}</span>`}
function renderSmuggling(){const c=$('#mainCard'),ar=$('#actionArea'),x=state.smuggling;if(!x)return;const officer=state.players.find(p=>p.id===x.officerId),isOfficer=me===x.officerId,round=x.round||0;if(state.phase==='smugglingBriefing'){const pages=[['밀수','7라운드 동안 가장 많은 C를 모으십시오. 매 라운드 한 명은 세관원, 나머지는 밀수업자가 됩니다.'],['가방 준비','밀수업자는 무작위 물품 5개 중 3개를 가방에 넣습니다. 실제 내용물은 본인만 볼 수 있습니다.'],['허위 신고','신고서에는 한 종류의 물품 3개만 적습니다. 실제 가방과 달라도 됩니다. 거짓말은 완전히 허용됩니다.'],['협상과 송금','Discord와 1:1 비밀대화로 세관원을 설득하십시오. C를 실제 송금할 수도 있습니다. 모든 약속은 강제되지 않습니다.'],['세관 검사','세관원은 기본 2개 가방만 검사합니다. 허위 신고면 압수·벌금, 정직 신고를 검사하면 세관원이 40C를 배상합니다. 통과 가방은 공개되지 않습니다.'],['수배도와 FINAL','밀수품을 통과시키면 수배도가 올라 적발 벌금이 커집니다. 7R FINAL은 검사권 3회. 최종 보유 C가 가장 높은 플레이어가 승리합니다.']];let pg=Number(sessionStorage.smRulePage||0);pg=Math.max(0,Math.min(5,pg));const [t,b]=pages[pg];c.innerHTML=`<div class="sm-brief"><div class="eyebrow">CUSTOMS BRIEFING · ${pg+1}/6</div><div class="sm-case">🧳</div><h1>${t}</h1><p>${b}</p></div>`;ar.innerHTML=`<div class="rule-nav"><button id="smPrev" ${pg===0?'disabled':''}>이전</button><button id="smReady" class="primary">룰 확인 완료</button><button id="smNext" ${pg===5?'disabled':''}>다음</button></div><p class="muted center">확인 ${x.briefingReady.length} / ${state.players.filter(p=>p.connected&&!p.isBot).length}</p>`;$('#smPrev').onclick=()=>{sessionStorage.smRulePage=pg-1;renderSmuggling()};$('#smNext').onclick=()=>{sessionStorage.smRulePage=pg+1;renderSmuggling()};$('#smReady').onclick=()=>socket.emit('smugglingBriefingReady',{},r=>!r.ok&&toast(r.error));return}
const prices=Object.entries(x.prices||{}).map(([k,v])=>`<div>${smItem(k)}<b>${v}C</b></div>`).join('');c.innerHTML=`<div class="sm-head"><div><div class="eyebrow">${round===7?'FINAL':'ROUND '+round} · ${state.phase.replace('smuggling','').toUpperCase()}</div><h2>👮 세관원 · ${esc(officer?.name||'')}</h2><p>${esc(x.messages||'')}</p></div><div class="sm-market">${prices}</div></div>`;
if(state.phase==='smugglingPack'){if(isOfficer){ar.innerHTML='<div class="sm-wait"><div class="sm-case">👮</div><h2>밀수업자들의 신고서를 기다리세요.</h2><p>잠시 후 협상이 시작됩니다.</p></div>';return}if(x.submitted.includes(me)){ar.innerHTML='<div class="sm-wait"><h2>🧳 가방 제출 완료</h2><p>다른 밀수업자를 기다리는 중…</p></div>';return}const hand=priv?.hand||[];ar.innerHTML=`<div class="sm-pack"><h3>내 물품 · 정확히 3개 선택</h3><div class="sm-hand">${hand.map((k,i)=>`<button data-sm-pick="${i}" class="${smSelected.includes(i)?'active':''}">${smItem(k)}</button>`).join('')}</div><div class="sm-declare"><label>세관 신고서<select id="smDeclare">${Object.entries(SMITEM).map(([k,v])=>`<option value="${k}">${v[0]} ${v[1]} ×3</option>`).join('')}</select></label><button id="smPackSubmit" class="primary">가방 + 신고서 제출</button></div><p class="muted">실제 가방과 신고 내용은 달라도 됩니다.</p></div>`;$$('[data-sm-pick]').forEach(b=>b.onclick=()=>{const i=+b.dataset.smPick;if(smSelected.includes(i))smSelected=smSelected.filter(v=>v!==i);else if(smSelected.length<3)smSelected.push(i);renderSmuggling()});$('#smPackSubmit').onclick=()=>{if(smSelected.length!==3)return toast('물품 3개를 선택해주세요.');socket.emit('smugglingPack',{indices:smSelected,declareItem:$('#smDeclare').value},r=>{if(!r.ok)toast(r.error);else smSelected=[]})};return}
if(state.phase==='smugglingNegotiate'||state.phase==='smugglingInspect'){const decl=state.players.filter(p=>p.id!==x.officerId).map(p=>{const d=x.declarations[p.id];return `<div class="sm-decl ${x.inspectionTargets.includes(p.id)?'target':''}"><b>${esc(p.name)}</b><span>${d?smItem(d.item)+' ×3':'미제출'}</span>${isOfficer&&state.phase==='smugglingInspect'?`<button data-sm-inspect="${p.id}">${smInspect.includes(p.id)?'검사 취소':'🔍 검사 후보'}</button>`:''}${p.id!==me?`<div class="sm-actions"><button data-sm-chat="${p.id}">대화</button><button data-sm-pay="${p.id}">송금</button></div>`:''}</div>`}).join('');ar.innerHTML=`<div class="sm-status"><div><b>내 자산</b><strong>${priv?.cash??x.cash[me]}C</strong></div><div><b>수배도</b><strong>${'🚨'.repeat(priv?.wanted||0)||'없음'}</strong></div><div><b>검사권</b><strong>${x.inspectionLimit}회</strong></div></div><div class="sm-declarations">${decl}</div>${isOfficer&&state.phase==='smugglingInspect'?'<button id="smInspectConfirm" class="primary wide">검사 대상 확정</button>':''}`;$$('[data-sm-inspect]').forEach(b=>b.onclick=()=>{const id=b.dataset.smInspect;if(smInspect.includes(id))smInspect=smInspect.filter(v=>v!==id);else if(smInspect.length<x.inspectionLimit)smInspect.push(id);else return toast(`최대 ${x.inspectionLimit}명입니다.`);renderSmuggling()});$('#smInspectConfirm')?.addEventListener('click',()=>socket.emit('smugglingInspect',{ids:smInspect},r=>{if(!r.ok)toast(r.error);else smInspect=[]}));$$('[data-sm-chat]').forEach(b=>b.onclick=()=>{const id=b.dataset.smChat,name=state.players.find(p=>p.id===id)?.name||'';const text=prompt(`${name}에게 보낼 비밀 메시지`);if(text)socket.emit('smugglingMessage',{toId:id,text},r=>!r.ok&&toast(r.error))});$$('[data-sm-pay]').forEach(b=>b.onclick=()=>{const id=b.dataset.smPay,name=state.players.find(p=>p.id===id)?.name||'';const amount=prompt(`${name}에게 송금할 C`,'30');if(amount)socket.emit('smugglingPay',{toId:id,amount:+amount},r=>r.ok?toast(`${amount}C 송금했습니다.`):toast(r.error))});return}
if(state.phase==='smugglingResult'){ar.innerHTML=`<div class="sm-results">${x.roundResults.map(q=>`<div class="${q.inspected?(q.truth?'honest':'caught'):'passed'}"><div><b>${q.inspected?'🔍':'✅'} ${esc(q.name)}</b><span>${q.inspected?(q.truth?'정직 신고':'허위 신고 적발'):'검사 없이 통과'}</span></div><div>${q.inspected?q.bag.map(smItem).join(' '):'<span class="muted">가방 내용 비공개</span>'}</div><strong>${q.penalty?`-${q.penalty}C`:q.compensation?`+${q.income+q.compensation}C`:`+${q.income}C`}</strong></div>`).join('')}</div>`;return}
if(state.phase==='smugglingFinal'){const medals=['🥇','🥈','🥉'];c.innerHTML='<div class="sm-final"><div class="eyebrow">FINAL RESULT</div><div class="sm-case">🧳</div><h1>국경 폐쇄</h1><p>7번의 거래와 거짓말이 모두 끝났습니다.</p></div>';ar.innerHTML=`<div class="sm-final-ranking">${x.finalRanking.map((q,i)=>`<div class="rank-${i+1}"><span>${medals[i]||`${i+1}위`} <b>${esc(q.name)}</b></span><strong>${q.value}C</strong></div>`).join('')}</div>`}
}

let forgeryDrawing=false,forgeryLast=null,forgeryTool='pen',forgeryColor='#111111',forgerySize=6,forgeryHistory=[];
function renderForgery(){const c=$('#mainCard'),a=$('#actionArea'),f=state.forgery;if(!f||!priv)return;const remain=state.deadline?Math.max(0,Math.ceil((state.deadline-Date.now())/1000)):0;if(state.phase==='forgeryDraw'){c.innerHTML=`<div class="forgery-stage"><div class="eyebrow">ROUND ${f.round} / ${f.totalRounds} · 그림 45초</div><h2>나의 제시어</h2><div class="forgery-word">${esc(priv.word)}</div><p>${priv.isImposter?'당신은 위조범입니다. 다른 사람과 비슷해 보이도록 그리세요.':'제시어를 그림으로 표현하세요. 글자와 숫자는 금지!'}</p></div>`;a.innerHTML=f.submitted.includes(me)?'<div class="result"><h2>그림 제출 완료</h2><p>다른 플레이어를 기다리는 중…</p></div>':`<div class="draw-wrap"><div class="draw-toolbar"><div class="draw-colors" aria-label="펜 색상">${['#111111','#ef4444','#f97316','#eab308','#22c55e','#3b82f6','#8b5cf6','#ec4899'].map((x,i)=>`<button type="button" class="draw-color ${i===0?'active':''}" data-color="${x}" style="--swatch:${x}" aria-label="색상 선택"></button>`).join('')}</div><div class="draw-tool-buttons"><button type="button" id="drawPen" class="active">✏️ 펜</button><button type="button" id="drawEraser">🧽 지우개</button><label class="draw-size">굵기 <input id="drawSize" type="range" min="2" max="28" value="6"></label><button type="button" id="drawUndo">↶ 되돌리기</button><button type="button" id="drawClear">전체 지우기</button></div></div><div class="forgery-canvas-box"><canvas id="forgeryCanvas" width="960" height="540"></canvas></div><div class="draw-submitbar"><span>마우스·터치로 자유롭게 그리세요.</span><button type="button" id="drawSubmit" class="primary">그림 제출 · ${remain}초</button></div></div>`;if(!f.submitted.includes(me))bindForgeryCanvas()}else if(state.phase==='forgeryVote'){c.innerHTML='<div class="forgery-stage"><div class="eyebrow">위조범 투표 · 30초</div><h2>누가 다른 제시어를 받았을까?</h2><p>그림만 보고 위조범을 찾아 투표하세요.</p></div>';const done=f.votesSubmitted.includes(me);a.innerHTML=`<div class="forgery-gallery">${state.players.map(p=>`<button class="forgery-drawing" data-vote="${p.id}" ${done||p.id===me?'disabled':''}><div>${f.drawings[p.id]?`<img src="${f.drawings[p.id]}">`:'<span>미제출</span>'}</div><b>${esc(p.name)}</b></button>`).join('')}</div>${done?'<p class="muted">투표 완료. 다른 플레이어를 기다리는 중…</p>':''}`;$$('[data-vote]').forEach(b=>b.onclick=()=>socket.emit('forgeryVote',{targetId:b.dataset.vote},r=>!r.ok&&toast(r.error)))}else{const rr=f.roundResult,imp=state.players.find(p=>p.id===rr?.imposterId);c.innerHTML=`<div class="forgery-stage result"><div class="eyebrow">${state.phase==='forgeryFinal'?'FINAL RESULT':`ROUND ${f.round} RESULT`}</div><h2>${rr?.caught?'🎯 위조범 검거!':'🎭 위조범 생존!'}</h2><p>위조범 <b>${esc(imp?.name||'')}</b> · 일반 제시어 <b>${esc(rr?.commonWord||'')}</b> · 위조범 제시어 <b>${esc(rr?.imposterWord||'')}</b></p></div>`;a.innerHTML='<div class="score-list">'+state.players.slice().sort((x,y)=>(f.scores[y.id]||0)-(f.scores[x.id]||0)).map((p,i)=>`<div><span>${i+1}위 · ${esc(p.name)}</span><b>${f.scores[p.id]||0}점</b></div>`).join('')+'</div>'}}
function bindForgeryCanvas(){const cv=$('#forgeryCanvas'),ctx=cv.getContext('2d');forgeryDrawing=false;forgeryLast=null;forgeryTool='pen';forgeryColor='#111111';forgerySize=6;forgeryHistory=[];ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.lineCap='round';ctx.lineJoin='round';const save=()=>{if(forgeryHistory.length>=20)forgeryHistory.shift();forgeryHistory.push(ctx.getImageData(0,0,cv.width,cv.height))};save();const pos=e=>{const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]};const apply=()=>{ctx.lineWidth=forgerySize;ctx.strokeStyle=forgeryTool==='eraser'?'#ffffff':forgeryColor;ctx.globalCompositeOperation='source-over'};const stop=e=>{if(!forgeryDrawing)return;forgeryDrawing=false;forgeryLast=null;try{if(e&&cv.hasPointerCapture(e.pointerId))cv.releasePointerCapture(e.pointerId)}catch{}save()};cv.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;forgeryDrawing=true;forgeryLast=pos(e);apply();try{cv.setPointerCapture(e.pointerId)}catch{};ctx.beginPath();ctx.arc(forgeryLast[0],forgeryLast[1],Math.max(1,forgerySize/2),0,Math.PI*2);ctx.fillStyle=forgeryTool==='eraser'?'#ffffff':forgeryColor;ctx.fill();e.preventDefault()});cv.addEventListener('pointermove',e=>{if(!forgeryDrawing)return;const q=pos(e);apply();ctx.beginPath();ctx.moveTo(forgeryLast[0],forgeryLast[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();forgeryLast=q;e.preventDefault()});cv.addEventListener('pointerup',stop);cv.addEventListener('pointercancel',stop);cv.addEventListener('pointerleave',e=>{if(e.buttons===0)stop(e)});$$('[data-color]').forEach(b=>b.onclick=()=>{forgeryColor=b.dataset.color;forgeryTool='pen';$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b));$('#drawPen').classList.add('active');$('#drawEraser').classList.remove('active')});$('#drawPen').onclick=()=>{forgeryTool='pen';$('#drawPen').classList.add('active');$('#drawEraser').classList.remove('active')};$('#drawEraser').onclick=()=>{forgeryTool='eraser';$('#drawEraser').classList.add('active');$('#drawPen').classList.remove('active')};$('#drawSize').oninput=e=>forgerySize=Number(e.target.value)||6;$('#drawUndo').onclick=()=>{if(forgeryHistory.length<=1)return;forgeryHistory.pop();ctx.putImageData(forgeryHistory[forgeryHistory.length-1],0,0)};$('#drawClear').onclick=()=>{ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);save()};$('#drawSubmit').onclick=()=>socket.emit('forgerySubmit',{image:cv.toDataURL('image/png')},r=>!r.ok&&toast(r.error))}

function renderCrocodile(){const c=$('#mainCard'),a=$('#actionArea'),g=state.crocodile,turn=state.players.find(p=>p.id===g?.turnPlayerId);if(state.phase==='crocodileResult'){const w=state.players.find(p=>p.id===g.winnerId);c.innerHTML=`<div class="croc-stage result"><div class="croc-face">🐊</div><h1>${esc(w?.name||'')} 승리!</h1><p>끝까지 악어에게 살아남았습니다.</p></div>`;a.innerHTML='';return}c.innerHTML=`<div class="croc-stage ${g?.bittenId?'bite':''}"><div class="eyebrow">악어의 입 · ${g?.round||1}번째</div><div class="croc-face">🐊</div><h2>${turn?.id===me?'당신의 차례입니다':`${esc(turn?.name||'')}님의 차례`}</h2><p>${esc(g?.lastAction||'')}</p></div>`;a.innerHTML=`<div class="croc-lives">${state.players.map(p=>`<div class="${(g.lives[p.id]||0)<=0?'dead':''}"><b>${esc(p.name)}</b><span>${'❤️'.repeat(g.lives[p.id]||0)||'💀'}</span></div>`).join('')}</div><div class="croc-mouth">${Array.from({length:g.teeth},(_,i)=>{const n=i+1,open=g.opened.includes(n);return `<button data-tooth="${n}" ${open||turn?.id!==me?'disabled':''} class="${open?'safe':''}">${open?'✓':n}</button>`}).join('')}</div>`;$$('[data-tooth]').forEach(b=>b.onclick=()=>socket.emit('crocodilePress',{tooth:+b.dataset.tooth},r=>!r.ok&&toast(r.error)))}

function renderTelepathy(){const c=$('#mainCard'),a=$('#actionArea'),t=state.telepathy;if(!t)return;const reverse=t.mode==='reverse';if(state.phase==='telepathyAnswer'){const done=t.submitted.includes(me);c.innerHTML=`<div class="telepathy-stage ${reverse?'reverse':''}"><div class="eyebrow">ROUND ${t.round} / ${t.totalRounds} · ${reverse?'청개구리 라운드':'텔레파시 라운드'} · 25초</div><div class="telepathy-icon">${reverse?'😈':'🧠'}</div><h2>${esc(t.prompt)}</h2><p>${reverse?'다른 사람과 겹치지 않는 답을 쓰세요. 혼자만 다른 답이면 +2점!':'다른 사람도 떠올릴 것 같은 답을 쓰세요. 같은 답을 쓴 인원수만큼 점수!'}</p></div>`;a.innerHTML=done?'<div class="result"><h2>답변 완료</h2><p>다른 플레이어의 생각을 기다리는 중…</p></div>':`<form id="telepathyForm" class="telepathy-form"><label class="telepathy-input-wrap"><span>나의 답</span><input id="telepathyInput" type="text" maxlength="20" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="done" inputmode="text" placeholder="답을 입력하세요"></label><button type="submit" class="primary">답변 확정</button></form><div id="telepathyTyping" class="muted center">한글 입력 중에도 내용이 유지됩니다. 최대 20자</div>`;if(!done){const form=$('#telepathyForm'),inp=$('#telepathyInput'),hint=$('#telepathyTyping');let composing=false;inp.addEventListener('compositionstart',()=>composing=true);inp.addEventListener('compositionend',()=>{composing=false;hint.textContent=`${inp.value.length}/20자`});inp.addEventListener('input',()=>hint.textContent=`${inp.value.length}/20자`);form.addEventListener('submit',e=>{e.preventDefault();if(composing){inp.blur();setTimeout(()=>form.requestSubmit(),0);return}const answer=inp.value.trim();if(!answer){toast('답변을 입력해주세요.');inp.focus();return}socket.emit('telepathySubmit',{answer},r=>{if(!r.ok){toast(r.error);inp.focus()}})});setTimeout(()=>inp.focus({preventScroll:true}),50)}}else{const final=state.phase==='telepathyFinal';c.innerHTML=`<div class="telepathy-stage ${reverse?'reverse':''}"><div class="eyebrow">${final?'FINAL RESULT':`ROUND ${t.round} RESULT`}</div><div class="telepathy-icon">${reverse?'😈':'✨'}</div><h2>${final?'텔레파시 게임 종료!':reverse?'청개구리 결과':'생각 공개!'}</h2><p>${esc(t.prompt)}</p></div>`;a.innerHTML=`<div class="telepathy-reveal">${state.players.map(p=>`<div><span><b>${esc(p.name)}</b><em>${esc(t.answers[p.id]||'미입력')}</em></span><strong>+${t.roundPoints[p.id]||0}</strong></div>`).join('')}</div><div class="score-list">${state.players.slice().sort((x,y)=>(t.scores[y.id]||0)-(t.scores[x.id]||0)).map((p,i)=>`<div><span>${i+1}위 · ${esc(p.name)}</span><b>${t.scores[p.id]||0}점</b></div>`).join('')}</div>`}}
